CREATE TABLE IF NOT EXISTS students (usn VARCHAR(20) PRIMARY KEY, name VARCHAR(100) NOT NULL, dob DATE NOT NULL, qr_code VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS college_staff (emp_id VARCHAR(20) PRIMARY KEY, name VARCHAR(100) NOT NULL, qr_code VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, name VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS issues (
  id BIGINT AUTO_INCREMENT PRIMARY KEY, token_id VARCHAR(20) UNIQUE NOT NULL,
  reporter_type VARCHAR(10) NOT NULL, reporter_id VARCHAR(20) NOT NULL, reporter_name VARCHAR(100) NOT NULL,
  title VARCHAR(200) NOT NULL, description TEXT NOT NULL, category VARCHAR(50) NOT NULL,
  selfie_path VARCHAR(200), video_path VARCHAR(200), photo_path VARCHAR(200), voice_path VARCHAR(200),
  status VARCHAR(30) NOT NULL, ai_score INT, ai_remark VARCHAR(255),
  assigned_to VARCHAR(100), resolved_by_name VARCHAR(100),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS issue_updates (id BIGINT AUTO_INCREMENT PRIMARY KEY, issue_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL, note VARCHAR(255), by_name VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (issue_id) REFERENCES issues(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, issue_id BIGINT NOT NULL, message VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (issue_id) REFERENCES issues(id));
